(()=>{const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');document.querySelectorAll('[data-video-hero]').forEach(hero=>{const video=hero.querySelector('video');if(!video)return;let pageActive=parent===window;let onScreen=true;let userPaused=reduceMotion.matches;let userGesture=false;video.muted=true;const bar=document.querySelector('.product-bar');if(bar)new ResizeObserver(()=>hero.style.setProperty('--video-bar',`${bar.offsetHeight}px`)).observe(bar);function sync(){const play=pageActive&&onScreen&&!document.hidden&&!userPaused;if(!play)video.pause();else if(video.paused)video.play().catch(()=>{});}
video.addEventListener('keydown',event=>{if(event.code!=='Space'&&event.key!=='Enter')return;event.preventDefault();userGesture=true;userPaused=!userPaused;sync();});video.addEventListener('loadedmetadata',sync);reduceMotion.addEventListener('change',event=>{if(!userGesture){userPaused=event.matches;sync();}});document.addEventListener('visibilitychange',sync);addEventListener('message',event=>{if(event.source===parent&&event.data?.namespace==='ctuav-demo'&&event.data.type==='view-active'){pageActive=!!event.data.active;sync();}});new IntersectionObserver(entries=>{onScreen=entries[0].isIntersecting;sync();},{threshold:.15}).observe(hero);sync();});})();